head.script:
scwin.gDepCd;
scwin.gEmpNo;
scwin.getPar, scwin.setPar;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox(panel_Top_2);
        $c.cm.PanelToGroupBox(panel_Top_3);
        MaxTab_01.setSelectedTabIndex(1);
        $c.stf.comboCbDataSetPeriod(cmb_PeriodTp_2);
        $c.stf.comboCbDataSetPeriod(cmb_PeriodTp_3);

        /*
        	fn_com_isur(txb_ISUR_CD_2, txb_COM_NM_2);
        	fn_com_isur(txb_ISUR_CD_3, txb_COM_NM_3);

        	Grd_com_isur_2.style.zIndex = 30;
        	Grd_com_isur_3.style.zIndex = 30;
         */

        Grd_com_isur_2.hide();
        Grd_com_isur_3.hide();
        await scwin.setCode();
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF21000.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

