/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    try {
        $c.stf.doLogSave("ULDSTF21000.xml", SCREN_PROCS_TP_CD_07); // 엑셀
        if (MaxTab_01.getSelectedTabIndex() === 1) {
            $c.data.downloadGridViewExcel(grd_List_1, {fileName: "현재 관리종목", type: "8"});
        } else if (MaxTab_01.getSelectedTabIndex() === 2) {
            $c.data.downloadGridViewExcel(grd_List_2, {fileName: "관리종목지정내역", type: "8"});
        } else if (MaxTab_01.getSelectedTabIndex() === 3) {
            $c.data.downloadGridViewExcel(grd_List_3, {fileName: "관리종목지정일자별 전후현황", type: "8"});
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF21000.btn_Excel_onclick" });
    }
};

