/**
 * @method
 * @name cmb_TeamList_2_OnSelChange
 * @description cmb_TeamList_2 선택 변경 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.cmb_TeamList_2_OnSelChange = function() {
    try {
        scwin.gDepCd = $c.cp.valueOfIndex(cmb_TeamList_2, "VALUE", cmb_TeamList_2.getSelectedIndex());
        if (scwin.gDepCd === '') {
            cmb_TeamList_2.setValue('');
        }
        dts_emp_2.UseFilter = true;
        dts_emp_2.Filter();
        dts_emp_2.sort("DEP_CD", 0);
        // dts_emp_2.sort(); // W-Craft 주석처리
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF21000.cmb_TeamList_2_OnSelChange" });
    }
};

/**
 * @method
 * @name dts_emp_2_OnFilter
 * @description emp 2 On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.dts_emp_2_OnFilter = function(row) {
    try {
        //  부서코드에  해당하는 사원을 가져온다.
        if (scwin.gDepCd === "") {
            // 전체일 경우 모두 보여준다.
            return true;
        } else {
            if (dts_emp_2.getCellData(row, "dep_cd") === scwin.gDepCd || dts_emp_2.getCellData(row, "dep_cd") === "") {
                return true;
            } else {
                return false;
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF21000.dts_emp_2_OnFilter" });
    }
};

