///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name setCode
 * @description set Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCode = async function() {
    scwin.gDepCd = js_dep_cd;
    scwin.gEmpNo = js_emp_no;

    //  기간 from~ to  셋팅
    const vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_SDate_2.setValue($c.ut.cGetMinusDate2(vCurDate, 7)); // 일주일전 날짜
    edt_EDate_2.setValue($c.ut.cGetToday("yyyymmdd")); // 현재날짜

    edt_SDate_3.setValue($c.ut.cGetMinusDate2(vCurDate, 7)); // 일주일전 날짜
    edt_EDate_3.setValue($c.ut.cGetToday("yyyymmdd")); // 현재날짜

    // 팀 리스트 박스(소속부서와 같은 상위부서인 팀)
    // dts_dep.DataID = "/CodeAction.do?method=listDepCdCode&For=R";
    const sbmOptions = {
        id : "sbm_dts_dep_2",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_dep_2=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // 담당자 리스트 박스(소속부서와 같은 상위부서인 팀원)
    const sbmOptions2 = {
        id : "sbm_dts_emp_2",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_emp_2=body.content",
        isProcessMsg : false
    };

