/**
 * @method
 * @name getPar
 * @description 넘길 인수를 지정하는 펑션
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getPar = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = "1";
    arrPar[1] = "07";
    arrPar[2] = txb_ADMISU_DESIGN_RSN_CD; // 코드값을 포함할 컨트롤
    arrPar[3] = txb_ADMISU_DESIGN_RSN_NM; // 명칭값을 포함할 컨트롤

    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    arrPar, length;
};

/**
 * @method
 * @name setPar
 * @description set Par 처리
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.setPar = function(arrPar) {
    txb_ADMISU_DESIGN_RSN_CD.setValue((arrPar.length >= 1 ? arrPar[0] : ""));
    txb_ADMISU_DESIGN_RSN_NM.setValue((arrPar.length >= 2 ? arrPar[1] : ""));
};
